const ctReleaseSculptVoice=function(){
 const pair=this.livePair,ctx=this.ctx;if(!pair||!ctx)return;
 this.livePair=null;const now=ctx.currentTime;
 for(const voice of pair.voices||[]){
  const gain=voice.gain;
  try{gain.gain.cancelScheduledValues(now);gain.gain.setValueAtTime(Math.max(.0001,gain.gain.value),now);gain.gain.exponentialRampToValueAtTime(.0001,now+.06);}catch{}
  for(const source of voice.sources){
   source.onended=()=>{this.active.delete(source);try{source.disconnect();}catch{}};
   try{source.stop(now+.07);}catch{this.active.delete(source);}
  }
  window.setTimeout(()=>{try{gain.disconnect();}catch{}},90);
 }
};
oc.prototype.releaseSculptDyad=ctReleaseSculptVoice;
oc.prototype.sculptDyad=function(tones,baseHz){
 if(!this.enabled||tones.length<2)return;
 try{
  const ctx=this.ensure(),base=this.fitBase(tones.map(tone=>tone.ratio),baseHz);
  const start=()=>{
   const kind=this.voice==='orchestra'?'orchestra':'piano';
   if(!this.livePair||this.livePair.kind!==kind||this.livePair.voices.length!==tones.length){
    this.stop();
    const voices=[];
    for(const tone of tones){
     const frequency=base*tone.ratio,gain=ctx.createGain(),now=ctx.currentTime;
     gain.gain.setValueAtTime(.0001,now);
     gain.gain.exponentialRampToValueAtTime((kind==='orchestra'?.12:.075)/Math.sqrt(tones.length),now+.035);
     gain.connect(ctx.destination);
     if(kind==='orchestra'){
      const midi=69+12*Math.log2(frequency/440),bank=ctSounds.prepare(ctx).filter(item=>item.kind==='orchestra');
      const sample=bank.reduce((a,b)=>Math.abs(a.root-midi)<=Math.abs(b.root-midi)?a:b);
      const source=ctx.createBufferSource();
      source.buffer=sample.buffer;source.loop=true;source.loopStart=2.2;source.loopEnd=4;
      source.playbackRate.value=2**((midi-sample.root)/12);
      source.connect(gain);source.start(now);this.active.add(source);
      voices.push({sources:[source],gain,root:sample.root,multipliers:[1]});
     }else{
      const partials=[{mul:1,level:.82,type:'sine'},{mul:2,level:.16,type:'sine'},{mul:3,level:.045,type:'triangle'}];
      const sources=partials.map(partial=>{
       const source=ctx.createOscillator(),level=ctx.createGain();
       source.type=partial.type;source.frequency.value=frequency*partial.mul;level.gain.value=partial.level;
       source.connect(level).connect(gain);source.start(now);this.active.add(source);return source;
      });
      voices.push({sources,gain,multipliers:partials.map(partial=>partial.mul)});
     }
    }
    this.livePair={kind,voices,osc:voices.map(voice=>voice.sources[0]),gain:voices.map(voice=>voice.gain)};
   }
   tones.forEach((tone,index)=>{
    const frequency=base*tone.ratio,voice=this.livePair.voices[index];if(!voice)return;
    if(this.livePair.kind==='orchestra'){
     const midi=69+12*Math.log2(frequency/440);
     voice.sources[0].playbackRate.setTargetAtTime(2**((midi-voice.root)/12),ctx.currentTime,.012);
    }else voice.sources.forEach((source,part)=>source.frequency.setTargetAtTime(frequency*voice.multipliers[part],ctx.currentTime,.012));
   });
  };
  ctx.state==='running'?start():ctx.resume().then(start).catch(()=>{});
 }catch(error){console.error('Infinity Sculpt audio failed',error);}
};

